VAR
    Overload_Timer : TON;
END_VAR

// Trip logic for M401_Conveyor_Drive
// Threshold: 51.9 A, Delay: 30 seconds
Overload_Timer(IN := (Motor_Current > 51.9) AND Motor_Running, PT := T#30S);

IF Overload_Timer.Q THEN
    Motor_Stop := TRUE;
    Overload_Alarm := TRUE;
END_IF;

IF Fault_Reset THEN
    Overload_Alarm := FALSE;
    Motor_Stop := FALSE;
END_IF;

